//! A profile `config.toml` generated by a configuration manager (spec:
//! distribution-and-update, NixOS and Home Manager modules): Home
//! Manager's `configMode = "managed"` regenerates the file on every
//! activation and leaves `config.generated.toml` beside it naming the
//! generator and the option that owns the file. Every writer then
//! refuses (exit 77) instead of making an edit the next activation would
//! silently undo.

use std::path::Path;

use pmt_core::error::{Error, codes};
use serde::Deserialize;

/// The marker beside a generated `config.toml`.
pub const MARKER_FILE: &str = "config.generated.toml";

#[derive(Debug, Deserialize)]
struct Marker {
    generator: String,
    option: String,
}

/// Fails when `profile_dir`'s `config.toml` is generated.
///
/// # Errors
///
/// `config.managed_key` (77) naming the generator and its option; an
/// unreadable marker is treated as present (fail closed).
pub fn check_writable(profile_dir: &Path) -> Result<(), Error> {
    let path = profile_dir.join(MARKER_FILE);
    let text = match std::fs::read_to_string(&path) {
        Ok(text) => text,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(()),
        Err(e) => return Err(Error::io(&codes::CONFIG_MANAGED_KEY, &path, &e)),
    };
    let (generator, option) = match toml::from_str::<Marker>(&text) {
        Ok(m) => (m.generator, m.option),
        Err(_) => (
            "a configuration manager".to_owned(),
            path.display().to_string(),
        ),
    };
    Err(Error::new(
        &codes::CONFIG_MANAGED_KEY,
        format!(
            "config.toml is generated by {generator}; edits would be lost on the next activation"
        ),
    )
    .with_hint(format!("change {option} instead")))
}

#[cfg(test)]
mod tests {
    use super::{MARKER_FILE, check_writable};

    #[test]
    fn a_generated_config_refuses_writes_naming_the_option() {
        let dir = tempfile::tempdir().unwrap();
        assert!(check_writable(dir.path()).is_ok());
        std::fs::write(
            dir.path().join(MARKER_FILE),
            "generator = \"Home Manager\"\noption = \"programs.prometheus.settings\"\n",
        )
        .unwrap();
        let err = check_writable(dir.path()).unwrap_err();
        assert_eq!(err.code().code, "config.managed_key");
        assert!(err.message().contains("generated by Home Manager"), "{err}");
        assert_eq!(
            err.hint(),
            Some("change programs.prometheus.settings instead")
        );
    }
}
